contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take a callee and arbitrary data. No Ether needs to be sent.
    function run(address callee, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Record our balance before calling c.forward
        uint256 balBefore = address(this).balance;

        bool reverted;
        // Call c.forward and capture whether it reverted
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // If the call did not revert, then (1) our balance must be unchanged
        // and (2) the low-level call inside forward must have returned success.
        // We cannot directly observe the inner low-level call return value, but
        // since forward uses require(_s) after the call, non-reversion implies _s == true.
        assert(reverted || (address(this).balance == balBefore));
    }

    receive() external payable { }
}

